from collections import deque
from typing import Dict, List, Optional

Theory = Dict[str, List[str]]

def bfs(axioms, a, b) -> Optional[int]:
    if a == b: return 0
    dist = {a: 0}; q = deque([a])
    while q:
        x = q.popleft()
        for y in axioms.get(x, []):
            if y not in dist:
                dist[y] = dist[x] + 1
                if y == b: return dist[y]
                q.append(y)
    return None

def chain(n: int):
    t = {k: [k + 1] for k in range(n)}; t[n] = []; return t

def main() -> None:
    n = 10
    src, tgt = chain(n), chain(2 * n)
    for a in range(n + 1):
        for b in range(a, n + 1):
            d = bfs(src, a, b); d2 = bfs(tgt, 2 * a, 2 * b)
            assert d2 == 2 * d, (a, b, d, d2)
    print("d(2a,2b) = 2*d(a,b) EXACTLY for all 0<=a<=b<=", n)

    # shortcut theory: strict triangle inequality
    sc = {"a": ["b", "d"], "b": ["c"], "c": ["d"], "d": []}
    direct = bfs(sc, "a", "d")
    detour = bfs(sc, "a", "c") + bfs(sc, "c", "d")
    print(f"shortcut: d(a,d)={direct} < detour {detour} -> strict (non-rigid)")

if __name__ == "__main__":
    main()

